-- Import da planilha 'Forcast_Gustavo_com_enderecos.xlsx' (03/09/2026):
-- enderecos/coordenadas mais completos, dados de funil/alerta financeiro e
-- historico + forecast de vendas por produto, por cliente.

-- 1) Novos campos dinamicos em Clientes
on conflict (chave) do nothing;

-- 2) Tabela de historico + forecast de vendas por produto
create table historico_vendas (
  id uuid primary key default gen_random_uuid(),
  cliente_id uuid references clientes(id) on delete cascade,
  cliente_nome text not null,
  produto text not null,
  origem text,
  qtd_2023 numeric, fat_2023 numeric,
  qtd_2024 numeric, fat_2024 numeric,
  qtd_2025 numeric, fat_2025 numeric,
  qtd_2025_janjul numeric, fat_2025_janjul numeric,
  qtd_2025_2sem numeric, fat_2025_2sem numeric,
  qtd_2026 numeric, fat_2026_janjul numeric,
  ultima_compra date,
  created_at timestamptz not null default now()
);
create index historico_vendas_cliente_id_idx on historico_vendas(cliente_id);

